"""Legacy Meridian CRM numeric division semantics."""

from __future__ import annotations


def _coerce_numeric(value: object) -> float:
    """Coerce legacy numeric-context values to float, defaulting to zero."""
    if value is None or value == "":
        return 0.0
    try:
        return float(value)
    except (TypeError, ValueError, OverflowError):
        return 0.0


def safe_div(a, b) -> tuple[float, list[str]]:
    """Perform division using Meridian CRM legacy division-by-zero behavior."""
    numerator = _coerce_numeric(a)
    denominator = _coerce_numeric(b)

    if denominator == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        return numerator / denominator, []
    except Exception:
        return 0.0, []
